WITH exploded AS (SELECT id, plan, effective_from, EXPLODE(tier_limits) AS element FROM price_tiers) SELECT id, plan, effective_from, element, CUME_DIST() OVER (PARTITION BY plan ORDER BY element NULLS FIRST) element_cume_dist, MAX(element) OVER (PARTITION BY plan) plan_max_element, DENSE_RANK() OVER (PARTITION BY plan ORDER BY element DESC NULLS LAST) element_dense_rank FROM exploded
